    answer:'함수 : 합계 / 참조 : 1분기!$B$2:$D$6 · 2분기!$B$2:$D$6\n☑ 첫 행  ☑ 왼쪽 열  ☑ 원본 데이터에 연결\n결과 : 노트북 215 / 모니터 380 / 키보드 630 / 마우스 410 / 프린터 60',
