    problem:'다음 두 쿼리를 작성하시오.\n▸ <실적상위3> : <사원> 테이블에서 실적이 높은 상위 3명을 조회 (사번, 사원명, 부서명, 실적)\n▸ <중복거래처> : <주문> 테이블에서 두 번 이상 주문한 거래처와 그 건수를 조회\n▸ 두 쿼리 모두 실적·건수 내림차순으로 정렬할 것',
