    problem:'<주문> 테이블에 대해 다음 쿼리를 차례로 작성하시오.\n▸ <주문백업> : 2025년 주문 자료만 <주문2025> 라는 새 테이블로 저장하는 쿼리\n▸ <취소삭제> : 상태가 "취소" 인 주문을 삭제하는 쿼리\n▸ 두 쿼리 모두 실행 전에 결과를 데이터시트 보기로 확인할 것',
