    '★표시 형식 / 맞춤 / 글꼴 / 테두리 / 채우기 / 보호★ — 모두 ★Ctrl+1★ 한 창에 있다.',
    '★보호 탭의 "잠금"은 시트 보호를 걸어야 비로소 작동★ 한다 — 이 탭만 눌러서는 아무 변화가 없다.'
